// Script -> scenario compiler.
//
// A script is a plain-text flow: one command per line, readable by someone who
// has never seen the driver. It compiles to a normal scenario module, so the
// generated file is inspectable and hand-editable — the script is a starting
// point, never a black box.
//
//   node script.mjs ../scripts/pricing-tour.demo [-o ../scenarios/pricing-tour.mjs]
//
// driver.mjs also accepts a script directly and compiles it on the way in.
//
// Grammar: see scripts/feature.demo and the README.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));

const GENERATED_MARKER = '@generated by pipeline/script.mjs';

// Marks a selector that states an intent and has not been resolved to a real
// one yet. Never reaches a scenario: compileScript swaps it or refuses.
export const ASK_PREFIX = 'ask:';

// Resolutions live beside the script rather than inside it, so the .demo keeps
// saying what you meant while the machine-found selector stays reviewable on
// its own. Keyed by the intent text, not by the selector name, so renaming a
// selector or reordering the block does not orphan a resolution.
export const selectorsSidecarPath = (scriptPath) =>
  scriptPath ? scriptPath.replace(/\.[^.\\/]+$/, '') + '.selectors.json' : null;

export function readSidecar(scriptPath) {
  const p = selectorsSidecarPath(scriptPath);
  if (!p || !fs.existsSync(p)) return { path: p, resolved: {}, meta: null };
  let doc;
  try {
    doc = JSON.parse(fs.readFileSync(p, 'utf8').replace(/^﻿/, ''));
  } catch (err) {
    throw new Error(`${p} is not valid JSON: ${err.message}`);
  }
  const resolved = {};
  for (const [intent, entry] of Object.entries(doc.selectors ?? {})) {
    const spec = typeof entry === 'string' ? entry : entry?.spec;
    if (typeof spec === 'string' && spec.trim()) resolved[intent] = spec.trim();
  }
  return { path: p, resolved, meta: doc };
}

const HEADER_KEYS = new Set([
  'name',
  'description',
  'target',
  'app',
  'start',
  'viewport',
  'match',
  'selectors',
  'intro',
  'outro',
]);

const DEFAULT_WAIT_MS = 15000;
const DEFAULT_APPEAR_MS = 20000;
const DEFAULT_GONE_MS = 60000;
const DEFAULT_SCROLL_PX = 240;

// ---- lexing helpers ----

class ScriptError extends Error {
  constructor(file, lineNo, message) {
    super(`${file}:${lineNo}: ${message}`);
    this.name = 'ScriptError';
  }
}

// Strip a trailing # comment. A '#' only starts a comment at the start of the
// line, or when it is surrounded by whitespace — otherwise `css #search` would
// lose its id selector. Quoted strings are never treated as comments.
function stripComment(line) {
  let quote = null;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (quote) {
      if (ch === '\\') i++;
      else if (ch === quote) quote = null;
      continue;
    }

    if (ch === '"' || ch === "'") {
      quote = ch;
      continue;
    }

    if (ch !== '#') continue;

    const isComment =
      i === 0 || (/\s/.test(line[i - 1]) && (i === line.length - 1 || /\s/.test(line[i + 1])));

    if (isComment) return line.slice(0, i);
  }

  return line;
}

function parseDuration(text, fail) {
  const m = /^(\d+(?:\.\d+)?)\s*(ms|s)?$/i.exec(String(text).trim());
  if (!m) fail(`"${text}" is not a duration (try 800ms, 2s, 2.5s)`);

  const value = Number(m[1]);
  const ms = (m[2] ?? 'ms').toLowerCase() === 's' ? value * 1000 : value;
  return Math.round(ms);
}

// pull a trailing "within 20s" / "for 20s" off a command's argument text
function splitTimeout(rest, fail) {
  const m = /^(.*?)\s+(?:within|for)\s+(\d+(?:\.\d+)?\s*(?:ms|s)?)$/i.exec(rest.trim());
  if (!m) return { rest: rest.trim(), timeoutMs: null };
  return { rest: m[1].trim(), timeoutMs: parseDuration(m[2], fail) };
}

const unquote = (s) => s.replace(/\\(.)/g, '$1');

// ---- selector specs ----

// A spec source is one of:
//   @name                a selector defined in the `selectors:` block
//   button "A" or "B"    btn: spec, alternatives joined with |
//   text "A"             ::-p-text(A)
//   css <raw>            a puppeteer selector, verbatim
//   ask "description"    resolved against the live DOM before the take
//   "A"                  defaults by command: click -> button, others -> text
//
// ---- why `ask` exists, and why it resolves BEFORE the take ----
//
// Every other kind here is a hardcoded handle onto the DOM, and that is the
// most brittle thing in a script: `btn:` needs the text exact, an avatar button
// flips between initials and an alt-named image, and a redesign silently
// invalidates the lot. Worse, the wording of a *generated* answer changes
// between runs, which is why the anchors in feature.demo had to be rewritten to
// wait on completion rather than on text.
//
// `ask` states the intent instead — `composer = ask "the message box at the
// bottom of the chat"` — and the concrete selector is found by driving the real
// app through the Claude in Chrome extension and written to a sidecar. Re-run
// the resolve step after a redesign and the script itself does not change.
//
// The resolution happens before recording rather than during it, and that is
// not a preference. driver.mjs stamps narration cues at wall-clock time while
// the screencast runs, so the take's timing IS the video timeline: a model
// round-trip mid-run would insert its own latency into the finished video as
// dead air, and no two takes would cut the same way. Resolved up front, the
// take stays deterministic and full-rate, and the sidecar is a reviewable
// artifact rather than a decision made live and forgotten.
function parseSpec(source, { defaultKind, fail }) {
  const src = source.trim();
  if (!src) fail('expected a selector');

  if (src.startsWith('@')) {
    const name = src.slice(1).trim();
    if (!/^[A-Za-z_]\w*$/.test(name)) fail(`"@${name}" is not a valid selector name`);
    return { ref: name };
  }

  const m = /^(button|btn|text|css|sel|selector|ask|describe)\s+([\s\S]+)$/i.exec(src);
  const kind = (m ? m[1] : defaultKind).toLowerCase();
  const rest = (m ? m[2] : src).trim();

  if (kind === 'ask' || kind === 'describe') {
    const quoted = /^"((?:[^"\\]|\\.)*)"$/.exec(rest);
    const intent = (quoted ? unquote(quoted[1]) : rest).trim();
    if (!intent) fail('ask takes a quoted description, e.g. ask "the search box in the header"');
    if (intent.length < 8) {
      fail(`ask description "${intent}" is too vague to resolve — say where it is and what it does`);
    }
    // The sentinel travels through the registry as an ordinary spec string and
    // is swapped for the resolved selector at compile time; anything left
    // unresolved is a compile error rather than a guess.
    return { spec: `${ASK_PREFIX}${intent}`, label: intent, intent };
  }

  if (kind === 'css' || kind === 'sel' || kind === 'selector') {
    return { spec: rest, label: null };
  }

  const quoted = [...rest.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((q) => unquote(q[1]));
  const texts = quoted.length ? quoted : [rest];

  if (texts.some((t) => !t.length)) fail('empty selector text');

  if (kind === 'button' || kind === 'btn') {
    return { spec: `btn:${texts.join('|')}`, label: texts[0] };
  }

  if (texts.length > 1) {
    fail('text selectors take a single string; use `button "A" or "B"` for alternatives');
  }

  return { spec: `::-p-text(${texts[0]})`, label: texts[0] };
}

// ---- SEL registry ----

function slug(label, fallback) {
  const words = String(label ?? '')
    .replace(/[^A-Za-z0-9 ]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 4);

  if (!words.length) return fallback;

  const name =
    words[0].toLowerCase() +
    words
      .slice(1)
      .map((w) => w[0].toUpperCase() + w.slice(1).toLowerCase())
      .join('');

  return /^[A-Za-z_]/.test(name) ? name.slice(0, 30) : fallback;
}

class SelRegistry {
  constructor() {
    this.byName = new Map(); // name -> spec
    this.bySpec = new Map(); // spec -> name
    this.auto = 0;
  }

  define(name, spec, fail) {
    if (this.byName.has(name) && this.byName.get(name) !== spec) {
      fail(`selector "${name}" is already defined as ${this.byName.get(name)}`);
    }
    this.byName.set(name, spec);
    if (!this.bySpec.has(spec)) this.bySpec.set(spec, name);
    return name;
  }

  // resolve a parsed spec to a SEL key, registering it if new
  keyFor(parsed, fail) {
    if (parsed.ref) {
      if (!this.byName.has(parsed.ref)) {
        fail(`selector "@${parsed.ref}" is not defined (add it under \`selectors:\`)`);
      }
      return parsed.ref;
    }

    const existing = this.bySpec.get(parsed.spec);
    if (existing) return existing;

    const base = slug(parsed.label, `sel${++this.auto}`);
    let name = base;
    let n = 2;
    while (this.byName.has(name)) name = `${base}${n++}`;

    this.byName.set(name, parsed.spec);
    this.bySpec.set(parsed.spec, name);
    return name;
  }
}

// ---- parser ----

export function parseScript(src, { file = 'script' } = {}) {
  const meta = {
    name: null,
    description: null,
    target: null,
    app: null,
    startUrl: null,
    viewport: null,
    match: [],
    intro: null,
    outro: null,
  };

  const sel = new SelRegistry();
  const root = [];
  const stack = [root]; // innermost block last
  const blockOpeners = []; // line numbers of unclosed `if`s

  let mode = null; // 'selectors' while inside the selectors block
  let sawStep = false;

  const lines = src.split(/\r?\n/);

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const fail = (msg) => {
      throw new ScriptError(file, lineNo, msg);
    };

    const line = stripComment(lines[i]).trim();
    if (!line) continue;

    // header directives: key: value
    const dir = /^([A-Za-z][\w-]*)\s*:\s*(.*)$/.exec(line);
    if (dir && HEADER_KEYS.has(dir[1].toLowerCase())) {
      const key = dir[1].toLowerCase();
      const value = dir[2].trim();

      if (sawStep && key !== 'selectors') {
        fail(`"${key}:" must come before the first beat`);
      }

      mode = null;

      switch (key) {
        case 'selectors':
          if (value) fail('`selectors:` takes no value; put definitions on the lines below');
          mode = 'selectors';
          break;
        case 'viewport': {
          const v = /^(\d+)\s*[x×]\s*(\d+)$/i.exec(value);
          if (!v) fail(`viewport must look like 1440x810, got "${value}"`);
          meta.viewport = { width: Number(v[1]), height: Number(v[2]) };
          break;
        }
        case 'match':
          meta.match = value
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean);
          break;
        case 'start':
          meta.startUrl = value;
          break;
        default:
          meta[key] = value;
      }
      continue;
    }

    // selector definitions inside the selectors block
    if (mode === 'selectors') {
      const def = /^([A-Za-z_]\w*)\s*=\s*(.+)$/.exec(line);
      if (def) {
        const parsed = parseSpec(def[2], { defaultKind: 'text', fail });
        if (parsed.ref) fail('a selector definition cannot reference another selector');
        sel.define(def[1], parsed.spec, fail);
        continue;
      }
      mode = null; // anything else ends the block and falls through as a step
    }

    // `let name = spec` works anywhere
    const let_ = /^let\s+([A-Za-z_]\w*)\s*=\s*(.+)$/i.exec(line);
    if (let_) {
      const parsed = parseSpec(let_[2], { defaultKind: 'text', fail });
      if (parsed.ref) fail('a selector definition cannot reference another selector');
      sel.define(let_[1], parsed.spec, fail);
      continue;
    }

    // steps
    const [verbRaw, ...restParts] = line.split(/\s+/);
    const verb = verbRaw.toLowerCase();
    const rest = restParts.join(' ').trim();
    const block = stack[stack.length - 1];
    const push = (step) => {
      sawStep = true;
      block.push({ ...step, lineNo });
    };

    const specKey = (source, defaultKind) =>
      sel.keyFor(parseSpec(source, { defaultKind, fail }), fail);

    switch (verb) {
      case 'beat':
        push({ op: 'beat', label: rest || `beat ${block.length + 1}` });
        break;

      case 'note':
        push({ op: 'note', text: rest });
        break;

      case 'say': {
        // narration cue: timestamped where it appears in the flow, rendered to
        // speech later. Does not block — the voice runs over the visuals.
        const lit = /^"((?:[^"\\]|\\.)*)"$/.exec(rest.trim());
        if (!lit) fail('say takes a quoted line, e.g. say "Here are the totals."');
        push({ op: 'say', text: unquote(lit[1]) });
        break;
      }

      case 'wait': {
        const { rest: target, timeoutMs } = splitTimeout(rest, fail);

        // `wait <sel> gone` is the complement: wait for it to disappear.
        // The usual way to wait out work of unknown length (spinner, Stop
        // button) without guessing the wording of the result.
        const g = /^(.*?)\s+(?:gone|to go|disappears?)$/i.exec(target);
        if (g) {
          push({
            op: 'waitGone',
            sel: specKey(g[1], 'text'),
            timeoutMs: timeoutMs ?? DEFAULT_GONE_MS,
          });
          break;
        }

        push({ op: 'wait', sel: specKey(target, 'text'), timeoutMs: timeoutMs ?? DEFAULT_WAIT_MS });
        break;
      }

      case 'click':
        push({ op: 'click', sel: specKey(rest, 'button') });
        break;

      case 'hover':
        push({ op: 'hover', sel: specKey(rest, 'text') });
        break;

      case 'hold':
        push({ op: 'hold', ms: parseDuration(rest, fail) });
        break;

      case 'type': {
        // type "text" into <spec>   |   type secret <name> into <spec>
        const secret = /^secret\s+([A-Za-z_]\w*)\s+into\s+(.+)$/i.exec(rest);
        if (secret) {
          push({ op: 'type', secret: secret[1], sel: specKey(secret[2], 'css') });
          break;
        }

        const lit = /^"((?:[^"\\]|\\.)*)"\s+into\s+(.+)$/i.exec(rest);
        if (!lit) fail('type takes `type "text" into <selector>` or `type secret <name> into <selector>`');
        push({ op: 'type', text: unquote(lit[1]), sel: specKey(lit[2], 'css') });
        break;
      }

      case 'scroll': {
        const m = /^(down|up)(?:\s+(\d+))?$/i.exec(rest);
        if (!m) fail('scroll takes `scroll down [px]` or `scroll up [px]`');
        const px = m[2] ? Number(m[2]) : DEFAULT_SCROLL_PX;
        push({ op: 'scroll', px: m[1].toLowerCase() === 'up' ? -px : px });
        break;
      }

      case 'press':
      case 'key': {
        if (!rest) fail('press takes a key name, e.g. `press Enter`');
        push({ op: 'key', key: rest.split(/\s+/)[0] });
        break;
      }

      case 'open': {
        if (!rest) fail('open takes a path or URL, e.g. `open /pricing`');
        push({ op: 'open', url: rest.replace(/^"|"$/g, '') });
        break;
      }

      case 'login':
        if (rest) fail('login takes no arguments (credentials come from the target)');
        push({ op: 'login' });
        break;

      case 'logout':
        if (rest) fail('logout takes no arguments');
        push({ op: 'logout' });
        break;

      case 'if': {
        // if <spec> appears [within 20s]
        const { rest: head, timeoutMs } = splitTimeout(rest, fail);
        const m = /^(.*?)\s+appears$/i.exec(head);
        if (!m) fail('if takes `if <selector> appears [within 20s]` and ends with `end`');

        const step = {
          op: 'if',
          sel: specKey(m[1], 'text'),
          timeoutMs: timeoutMs ?? DEFAULT_APPEAR_MS,
          children: [],
          lineNo,
        };
        push(step);
        stack.push(step.children);
        blockOpeners.push(lineNo);
        break;
      }

      case 'end':
        if (stack.length === 1) fail('`end` without a matching `if`');
        stack.pop();
        blockOpeners.pop();
        break;

      default:
        fail(`unknown command "${verbRaw}"`);
    }
  }

  if (stack.length > 1) {
    throw new ScriptError(file, blockOpeners.pop(), '`if` block is never closed with `end`');
  }

  return { meta, sel: Object.fromEntries(sel.byName), steps: root };
}

// ---- codegen ----

const q = (s) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

function emitSteps(steps, indent, out) {
  const pad = ' '.repeat(indent);

  for (const step of steps) {
    switch (step.op) {
      case 'beat':
        out.push('');
        out.push(`${pad}// ${step.label}`);
        break;
      case 'note':
        out.push(`${pad}// ${step.text}`);
        break;
      case 'say':
        out.push(`${pad}d.say(${q(step.text)});`);
        break;
      case 'wait':
        out.push(`${pad}await d.waitSel(SEL.${step.sel}, ${step.timeoutMs});`);
        break;
      case 'waitGone':
        out.push(`${pad}await d.waitGone(SEL.${step.sel}, ${step.timeoutMs});`);
        break;
      case 'click':
        out.push(`${pad}await d.clickSel(SEL.${step.sel});`);
        break;
      case 'hover':
        out.push(`${pad}await d.hoverSel(SEL.${step.sel});`);
        break;
      case 'hold':
        out.push(`${pad}await d.hold(${step.ms});`);
        break;
      case 'type':
        out.push(
          step.secret
            ? `${pad}await d.type(SEL.${step.sel}, d.secret(${q(step.secret)}));`
            : `${pad}await d.type(SEL.${step.sel}, ${q(step.text)});`,
        );
        break;
      case 'scroll':
        out.push(`${pad}await d.wheel(${step.px});`);
        break;
      case 'key':
        out.push(`${pad}await d.key(${q(step.key)});`);
        break;
      case 'open':
        out.push(`${pad}await d.open(${q(step.url)});`);
        break;
      case 'login':
        out.push(`${pad}await d.login();`);
        break;
      case 'logout':
        out.push(`${pad}await d.logout();`);
        break;
      case 'if':
        out.push(`${pad}if (await d.appears(SEL.${step.sel}, ${step.timeoutMs})) {`);
        emitSteps(step.children, indent + 2, out);
        out.push(`${pad}}`);
        break;
      default:
        throw new Error(`no codegen for step "${step.op}"`);
    }
  }
}

// Every `ask` intent in a parsed script, in first-use order. This is the work
// list the resolve step takes into the browser.
export function askIntents(sel) {
  const seen = new Set();
  const out = [];
  for (const [name, spec] of Object.entries(sel)) {
    if (!String(spec).startsWith(ASK_PREFIX)) continue;
    const intent = String(spec).slice(ASK_PREFIX.length);
    if (seen.has(intent)) continue;
    seen.add(intent);
    out.push({ name, intent });
  }
  return out;
}

// `sourcePath` is a display string for the generated header; `scriptPath` is
// the real file on disk, which is what the sidecar sits beside. They are not
// the same — the header carries a repo-relative path for readability.
export function compileScript(
  src,
  { file = 'script', sourcePath = null, scriptPath = null, resolved = null } = {},
) {
  const { meta, sel, steps } = parseScript(src, { file });
  const warnings = [];

  // ---- resolve `ask` selectors ----
  // The sidecar beside the script is the default source; `resolved` overrides
  // it so a caller can compile against a resolution it holds in memory.
  const sidecar = resolved ? { path: null, resolved } : readSidecar(scriptPath);
  const unresolved = [];

  for (const [name, spec] of Object.entries(sel)) {
    if (!String(spec).startsWith(ASK_PREFIX)) continue;
    const intent = String(spec).slice(ASK_PREFIX.length);
    const hit = sidecar.resolved[intent];
    if (hit) sel[name] = hit;
    else unresolved.push({ name, intent });
  }

  // Refuse rather than fall back to guessing a selector from the description.
  // A wrong guess does not error here — it errors mid-take, after the browser
  // is up and the recording has started, which is the expensive place to fail.
  if (unresolved.length) {
    const list = unresolved.map((u) => `  ${u.name} = ask "${u.intent}"`).join('\n');
    throw new Error(
      `${unresolved.length} selector(s) still state an intent and have no resolution:\n${list}\n\n` +
        'Resolve them against the live app first — ask Claude to "resolve the selectors for ' +
        `${sourcePath ? path.basename(sourcePath) : file}", which drives the page through the ` +
        'Chrome extension and writes the sidecar:\n' +
        `  ${sidecar.path ?? (scriptPath ? selectorsSidecarPath(scriptPath) : '<script>.selectors.json')}\n` +
        'See README "Natural-language selectors".',
    );
  }

  const flat = (list) =>
    list.flatMap((s) => (s.op === 'if' ? [s, ...flat(s.children)] : [s]));
  const actions = flat(steps).filter((s) => !['beat', 'note', 'say'].includes(s.op));

  if (!actions.length) warnings.push('script has no steps — the take will be empty');

  const last = actions[actions.length - 1];
  if (last && last.op !== 'hold') {
    warnings.push(
      'script does not end on a `hold` — add one (~2s) so the final zoom can settle',
    );
  }

  const needsAuth = actions.some((s) => s.op === 'login' || s.op === 'logout');

  const head = [
    `// ${GENERATED_MARKER}`,
    `// source: ${sourcePath ?? file}`,
    '//',
    '// Safe to edit by hand — but recompiling the script overwrites it.',
    '// Run: node driver.mjs <this file> [--target <name>]',
  ];

  if (meta.description) head.push(`//`, `// ${meta.description}`);

  const body = [];

  if (meta.target) body.push(`export const TARGET = ${q(meta.target)};`);
  if (meta.app) body.push(`export const APP = ${q(meta.app)};`);
  if (meta.startUrl) body.push(`export const START_URL = ${q(meta.startUrl)};`);
  if (meta.viewport) {
    body.push(
      `export const VIEWPORT = { width: ${meta.viewport.width}, height: ${meta.viewport.height} };`,
    );
  }
  if (meta.match.length) {
    body.push(`export const PAGE_URL_MATCH = [${meta.match.map(q).join(', ')}];`);
  }

  // consumed by cards.mjs, not by the driver
  if (meta.intro) body.push(`export const INTRO = ${q(meta.intro)};`);
  if (meta.outro) body.push(`export const OUTRO = ${q(meta.outro)};`);

  const selEntries = Object.entries(sel);
  if (body.length) body.push('');
  body.push('export const SEL = {');
  for (const [name, spec] of selEntries) body.push(`  ${name}: ${q(spec)},`);
  body.push('};');
  body.push('');
  body.push('export async function run(d) {');

  const stepLines = [];
  emitSteps(steps, 2, stepLines);
  // drop the leading blank line the first `beat` emits
  while (stepLines.length && stepLines[0] === '') stepLines.shift();
  body.push(...stepLines);

  body.push('}');

  return {
    source: `${head.join('\n')}\n\n${body.join('\n')}\n`,
    meta,
    sel,
    warnings,
    needsAuth,
  };
}

export function isGeneratedScenario(file) {
  if (!fs.existsSync(file)) return true; // nothing to clobber
  return fs.readFileSync(file, 'utf8').includes(GENERATED_MARKER);
}

// ---- CLI ----

const invokedDirectly =
  process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (invokedDirectly) {
  const argv = process.argv.slice(2);
  let input = null;
  let output = null;
  let force = false;
  let print = false;
  let intentsOnly = false;

  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '-o' || a === '--out') output = argv[++i];
    else if (a === '--force') force = true;
    else if (a === '--print') print = true;
    else if (a === '--intents') intentsOnly = true;
    else if (!input) input = a;
    else {
      console.error(`unexpected argument "${a}"`);
      process.exit(1);
    }
  }

  if (!input) {
    console.error(
      'usage: node script.mjs <script.demo> [-o <scenario.mjs>] [--print] [--intents] [--force]',
    );
    process.exit(1);
  }

  const inPath = path.resolve(input);
  const src = fs.readFileSync(inPath, 'utf8');
  const base = path.basename(inPath).replace(/\.[^.]+$/, '');

  // --intents lists the `ask` selectors and what is already resolved, without
  // compiling. This is the work list for the resolve step, so it has to succeed
  // while resolutions are still missing — which compiling deliberately does not.
  if (intentsOnly) {
    const { sel } = parseScript(src, { file: path.basename(inPath) });
    const sidecar = readSidecar(inPath);
    const rows = askIntents(sel).map((a) => ({
      ...a,
      spec: sidecar.resolved[a.intent] ?? null,
    }));

    console.log(JSON.stringify({ script: inPath, sidecar: sidecar.path, selectors: rows }, null, 2));

    const missing = rows.filter((r) => !r.spec).length;
    console.error(
      rows.length
        ? `\n${rows.length} ask selector(s), ${missing} unresolved`
        : '\nno ask selectors in this script',
    );
    process.exit(0);
  }

  const { source, warnings } = compileScript(src, {
    file: path.basename(inPath),
    sourcePath: path.relative(path.join(HERE, '..'), inPath).split(path.sep).join('/'),
    scriptPath: inPath,
  });

  for (const w of warnings) console.warn(`warning: ${w}`);

  if (print) {
    console.log(source);
  } else {
    const outPath = path.resolve(output ?? path.join(HERE, '..', 'scenarios', `${base}.mjs`));

    if (!force && !isGeneratedScenario(outPath)) {
      console.error(
        `refusing to overwrite ${outPath}: it was not generated from a script.\n` +
          'Pass --force, or -o a different path.',
      );
      process.exit(1);
    }

    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, source);
    console.log(outPath);
    console.log(`\nnext: node driver.mjs ${path.relative(HERE, outPath).split(path.sep).join('/')}`);
  }
}
